7	namespace duckdb {
8	
9	unique_ptr<LogicalOperator> EmptyResultPullup::PullUpEmptyJoinChildren(unique_ptr<LogicalOperator> op) {
10		JoinType join_type = JoinType::INVALID;
11		D_ASSERT(op->type == LogicalOperatorType::LOGICAL_COMPARISON_JOIN ||
12		         op->type == LogicalOperatorType::LOGICAL_ANY_JOIN || op->type == LogicalOperatorType::LOGICAL_DELIM_JOIN ||
13		         op->type == LogicalOperatorType::LOGICAL_ASOF_JOIN || op->type == LogicalOperatorType::LOGICAL_EXCEPT);
14		switch (op->type) {
15		case LogicalOperatorType::LOGICAL_DELIM_JOIN:
16		case LogicalOperatorType::LOGICAL_ASOF_JOIN:
17		case LogicalOperatorType::LOGICAL_COMPARISON_JOIN:
18			join_type = op->Cast<LogicalComparisonJoin>().join_type;
19			break;
20		case LogicalOperatorType::LOGICAL_ANY_JOIN:
21			join_type = op->Cast<LogicalAnyJoin>().join_type;
22			break;
23		case LogicalOperatorType::LOGICAL_EXCEPT:
24			join_type = JoinType::ANTI;
25			break;
26		case LogicalOperatorType::LOGICAL_INTERSECT:
27			join_type = JoinType::SEMI;
28			break;
29		default:
30			break;
31		}
32	
33		switch (join_type) {
34		case JoinType::SEMI:
35		case JoinType::INNER: {
36			for (auto &child : op->children) {
37				if (child->type == LogicalOperatorType::LOGICAL_EMPTY_RESULT) {
38					op = make_uniq<LogicalEmptyResult>(std::move(op));
39					break;
40				}
41			}
42			break;
43		}
44		// For ANTI joins, if the right child is empty, the whole join collapses to the left child
45		case JoinType::ANTI: {
46			if (op->children[1]->type == LogicalOperatorType::LOGICAL_EMPTY_RESULT &&
47			    op->type != LogicalOperatorType::LOGICAL_EXCEPT) {
48				op = std::move(op->children[0]);
49				break;
50			}
51			if (op->children[0]->type == LogicalOperatorType::LOGICAL_EMPTY_RESULT) {
52				op = make_uniq<LogicalEmptyResult>(std::move(op));
53			}
54			break;
55		}
56		case JoinType::MARK:
57		case JoinType::SINGLE:
58		case JoinType::LEFT: {
59			if (op->children[0]->type == LogicalOperatorType::LOGICAL_EMPTY_RESULT) {
60				op = make_uniq<LogicalEmptyResult>(std::move(op));
61			}
62			break;
63		}
64		default:
65			break;
66		}
67		return op;
68	}
69	
70	unique_ptr<LogicalOperator> EmptyResultPullup::Optimize(unique_ptr<LogicalOperator> op) {
71		for (idx_t i = 0; i < op->children.size(); i++) {
72			op->children[i] = Optimize(std::move(op->children[i]));
73		}
74		switch (op->type) {
75		case LogicalOperatorType::LOGICAL_PROJECTION:
76		case LogicalOperatorType::LOGICAL_FILTER:
77		case LogicalOperatorType::LOGICAL_DISTINCT:
78		case LogicalOperatorType::LOGICAL_WINDOW:
79		case LogicalOperatorType::LOGICAL_GET:
80		case LogicalOperatorType::LOGICAL_INTERSECT:
81		case LogicalOperatorType::LOGICAL_PIVOT:
82		case LogicalOperatorType::LOGICAL_CROSS_PRODUCT: {
83			for (auto &child : op->children) {
84				if (child->type == LogicalOperatorType::LOGICAL_EMPTY_RESULT) {
85					op = make_uniq<LogicalEmptyResult>(std::move(op));
86					break;
87				}
88			}
89			return op;
90		}
91		case LogicalOperatorType::LOGICAL_MATERIALIZED_CTE: {
92			D_ASSERT(op->children.size() == 2);
93			if (op->children[1]->type == LogicalOperatorType::LOGICAL_EMPTY_RESULT) {
94				if (op->children[0]->HasSideEffects()) {
95					return op;
96				}
97				op = make_uniq<LogicalEmptyResult>(std::move(op));
98				break;
99			}
100			return op;
101		}
102		case LogicalOperatorType::LOGICAL_EXCEPT:
103		case LogicalOperatorType::LOGICAL_ANY_JOIN:
104		case LogicalOperatorType::LOGICAL_DELIM_JOIN:
105		case LogicalOperatorType::LOGICAL_ASOF_JOIN:
106		case LogicalOperatorType::LOGICAL_COMPARISON_JOIN: {
107			op = PullUpEmptyJoinChildren(std::move(op));
108			break;
109		}
110		default:
111			break;
112		}
113		return op;
114	}
115	
116	} // namespace duckdb
