43		D_ASSERT(join.children.size() == 2);
44		// now for the original join
45		// we take its left child, this is the side that we will duplicate eliminate
46		children.push_back(join.children[0]);
47	
48		// we replace it with a PhysicalColumnDataScan, that scans the ColumnDataCollection that we keep cached
49		// the actual chunk collection to scan will be created in the LeftDelimJoinGlobalState
50		auto &cached_scan = planner.Make<PhysicalColumnDataScan>(
51		    children[0].get().GetTypes(), PhysicalOperatorType::COLUMN_DATA_SCAN, estimated_cardinality, nullptr);
52		if (delim_idx.IsValid()) {
53			auto &cast_cached_scan = cached_scan.Cast<PhysicalColumnDataScan>();
54			cast_cached_scan.delim_index = delim_idx.GetIndex();
