268	bool TopNHeap::CheckBoundaryValues(DataChunk &sort_chunk, DataChunk &payload, TopNBoundaryValue &global_boundary) {
269		// get the global boundary value
270		auto current_boundary_val = global_boundary.GetBoundaryValue();
271		if (current_boundary_val.empty()) {
272			// no boundary value (yet) - don't do anything
273			return true;
274		}
275		if (current_boundary_val != boundary_val) {
276			// new boundary value - decode
277			boundary_val = std::move(current_boundary_val);
278			boundary_values.Reset();
279			CreateSortKeyHelpers::DecodeSortKey(string_t(boundary_val), boundary_values, 0, modifiers);
280			for (auto &col : boundary_values.data) {
281				col.SetVectorType(VectorType::CONSTANT_VECTOR);
282			}
283		}
284		boundary_values.SetChildCardinality(sort_chunk.size());
285	
286		// we have boundary values
287		// from these boundary values, determine which values we should insert (if any)
288		idx_t final_count = 0;
289	
290		SelectionVector remaining_sel(nullptr);
291		idx_t remaining_count = sort_chunk.size();
292		for (idx_t i = 0; i < orders.size() && remaining_count > 0; i++) {
293			if (remaining_sel.data()) {
294				compare_chunk.data[i].Slice(sort_chunk.data[i], remaining_sel, remaining_count);
295			} else {
296				compare_chunk.data[i].Reference(sort_chunk.data[i]);
297			}
298			bool is_last = i + 1 == orders.size();
299			idx_t true_count;
300			if (orders[i].null_order == OrderByNullType::NULLS_LAST) {
301				if (orders[i].type == OrderType::ASCENDING) {
302					true_count = VectorOperations::DistinctLessThan(compare_chunk.data[i], boundary_values.data[i],
303					                                                &remaining_sel, remaining_count, &true_sel, &false_sel);
304				} else {
305					true_count = VectorOperations::DistinctGreaterThanNullsFirst(compare_chunk.data[i],
306					                                                             boundary_values.data[i], &remaining_sel,
307					                                                             remaining_count, &true_sel, &false_sel);
308				}
309			} else {
310				D_ASSERT(orders[i].null_order == OrderByNullType::NULLS_FIRST);
311				if (orders[i].type == OrderType::ASCENDING) {
312					true_count = VectorOperations::DistinctLessThanNullsFirst(compare_chunk.data[i],
313					                                                          boundary_values.data[i], &remaining_sel,
314					                                                          remaining_count, &true_sel, &false_sel);
315				} else {
316					true_count =
317					    VectorOperations::DistinctGreaterThan(compare_chunk.data[i], boundary_values.data[i],
318					                                          &remaining_sel, remaining_count, &true_sel, &false_sel);
319				}
320			}
321	
322			if (true_count > 0) {
323				memcpy(final_sel.data() + final_count, true_sel.data(), true_count * sizeof(sel_t));
324				final_count += true_count;
325			}
326			idx_t false_count = remaining_count - true_count;
327			if (!is_last && false_count > 0) {
328				// check what we should continue to check
329				compare_chunk.data[i].Slice(sort_chunk.data[i], false_sel, false_count);
330				remaining_count = VectorOperations::NotDistinctFrom(compare_chunk.data[i], boundary_values.data[i],
331				                                                    &false_sel, false_count, &new_remaining_sel, nullptr);
332				remaining_sel.Initialize(new_remaining_sel);
333			} else {
334				break;
335			}
336		}
337		if (final_count == 0) {
338			return false;
339		}
340		if (final_count < sort_chunk.size()) {
341			sort_chunk.Slice(final_sel, final_count);
342			payload.Slice(final_sel, final_count);
343		}
344		return true;
345	}
346	
347	void TopNHeap::Sink(DataChunk &input, optional_ptr<TopNBoundaryValue> global_boundary) {
348		static constexpr idx_t SMALL_HEAP_THRESHOLD = 100;
349	
350		// compute the ordering values for the new chunk
351		sort_chunk.Reset();
352		executor.Execute(input, sort_chunk);
353	
354		if (global_boundary) {
355			// if we have a global boundary value check which rows pass before doing anything
356			if (!CheckBoundaryValues(sort_chunk, input, *global_boundary)) {
357				// nothing in this chunk can be in the final result
358				return;
359			}
360		}
361	
362		// construct the sort key from the sort chunk
363		sort_keys.Reset();
364		auto &sort_keys_vec = sort_keys.data[0];
365		CreateSortKeyHelpers::CreateSortKey(sort_chunk, modifiers, sort_keys_vec);
366	
367		if (heap_size <= SMALL_HEAP_THRESHOLD) {
368			AddSmallHeap(input, sort_keys_vec);
369		} else {
370			AddLargeHeap(input, sort_keys_vec);
371		}
372	
373		// if we modified the heap we might be able to update the global boundary
374		// note that the global boundary only applies to FULL heaps
375		if (heap.size() >= heap_size && global_boundary) {
376			global_boundary->UpdateValue(heap.front().sort_key);
377		}
378	}
379	
380	void TopNHeap::Combine(TopNHeap &other) {
381		// "other" is sorted at this point
382		idx_t match_count = 0;
383		// merge the heap of other into this
384		for (idx_t i = 0; i < other.heap.size(); i++) {
385			// heap is full - check the latest entry
386			auto &other_entry = other.heap[i];
387			auto &sort_key = other_entry.sort_key;
388			if (!EntryShouldBeAdded(sort_key)) {
389				break; // We can break out of the loop here since we sorted the heap
390			}
391			// add this entry
392			TopNEntry new_entry;
393			new_entry.sort_key = sort_key_heap.AddBlob(sort_key);
394			new_entry.index = heap_data.size() + match_count;
395			AddEntryToHeap(new_entry);
396	
397			matching_sel.set_index(match_count++, other_entry.index);
398			if (match_count >= STANDARD_VECTOR_SIZE) {
399				// flush
400				heap_data.Append(other.heap_data, matching_sel, match_count, VectorAppendMode::ALLOW_RESIZE);
401				match_count = 0;
402			}
403		}
404		if (match_count > 0) {
405			// flush
406			heap_data.Append(other.heap_data, matching_sel, match_count, VectorAppendMode::ALLOW_RESIZE);
407			match_count = 0;
408		}
409		Reduce();
410	}
411	
412	void TopNHeap::Finalize() {
413		std::sort(heap.begin(), heap.end());
414	}
415	
416	void TopNHeap::Reduce() {
417		if (heap_data.size() < ReduceThreshold()) {
418			// only reduce when we pass the reduce threshold
419			return;
420		}
421		// we have too many values in the heap - reduce them
422		StringHeap new_sort_heap;
423		DataChunk new_heap_data;
424		new_heap_data.Initialize(allocator, payload_types, heap.size());
425	
426		SelectionVector new_payload_sel(heap.size());
427		for (idx_t i = 0; i < heap.size(); i++) {
428			auto &entry = heap[i];
429			// move the sort key to the new sort heap
430			entry.sort_key = new_sort_heap.AddBlob(entry.sort_key);
431			// move this heap entry to position X in the payload chunk
432			new_payload_sel.set_index(i, entry.index);
433			entry.index = i;
434		}
435	
436		// copy over the data from the current payload chunk to the new payload chunk
437		new_heap_data.Slice(heap_data, new_payload_sel, heap.size());
438		new_heap_data.Flatten();
439	
440		sort_key_heap.Destroy();
441		sort_key_heap.Move(new_sort_heap);
442		heap_data.Reference(new_heap_data);
443	}
444	
445	void TopNHeap::InitializeScan(TopNScanState &state, bool exclude_offset) {
446		auto heap_copy = heap;
447		state.scan_order.resize(heap_copy.size());
448	
449		// we sorted the heap in Finalize(), so we can sequentially here
450		// we do this because sorting the heap is much more efficient than popping one by one
451		for (idx_t i = 0; i < heap_copy.size(); i++) {
452			state.scan_order[i] = UnsafeNumericCast<sel_t>(heap_copy[i].index);
453		}
454	
455		state.pos = exclude_offset ? offset : 0;
456	}
457	
458	void TopNHeap::Scan(TopNScanState &state, DataChunk &chunk, idx_t &pos) {
459		if (pos >= state.scan_order.size()) {
460			return;
461		}
462		SelectionVector sel(state.scan_order.data() + pos, state.scan_order.size() - pos);
463		idx_t count = MinValue<idx_t>(STANDARD_VECTOR_SIZE, state.scan_order.size() - pos);
464		pos += STANDARD_VECTOR_SIZE;
465	
466		chunk.Reset();
467		chunk.Slice(heap_data, sel, count);
468	}
